//! Byte-exact reimplementation of C++ `std::cout << v` default formatting for
//! `double` (defaultfloat, precision 6) — equivalent to glibc `printf("%g", v)`.
//!
//! The exact decimal expansion of the binary value is produced with a simple
//! arbitrary-precision unsigned integer, then rounded to 6 significant digits
//! using round-half-even (glibc behaviour on exact decimal ties), then laid out
//! per the `%g` rules: scientific notation iff the decimal exponent is < -4 or
//! >= 6, with trailing zeros (and a dangling decimal point) stripped.

/// Format `v` exactly as C++ `std::cout << v` would with default flags.
pub fn format_cpp_double(v: f64) -> String {
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if v.is_infinite() {
        return if v.is_sign_negative() { "-inf".to_string() } else { "inf".to_string() };
    }
    let neg = v.is_sign_negative();
    if v == 0.0 {
        return if neg { "-0".to_string() } else { "0".to_string() };
    }

    // Decompose: |v| = mantissa * 2^e2
    let bits = v.abs().to_bits();
    let exp_field = (bits >> 52) & 0x7ff;
    let frac = bits & 0x000f_ffff_ffff_ffff;
    let (mantissa, e2): (u64, i32) = if exp_field == 0 {
        (frac, -1074) // subnormal
    } else {
        (frac | (1u64 << 52), exp_field as i32 - 1075)
    };

    // Build the exact decimal digits of |v| using a bignum (Vec<u32>,
    // little-endian base 2^32), plus the position of the decimal point:
    // |v| = digits (as an integer string) with `point_pos` digits left of the
    // decimal point (point_pos may be <= 0).
    let mut big: Vec<u32> = Vec::new();
    let mut m = mantissa;
    while m > 0 {
        big.push((m & 0xffff_ffff) as u32);
        m >>= 32;
    }

    if e2 >= 0 {
        shl_bits(&mut big, e2 as u32);
        let digits = to_decimal_digits(&big);
        let point_pos = digits.len() as i32;
        format_g(digits, point_pos, neg)
    } else {
        // |v| = mantissa / 2^k = mantissa * 5^k / 10^k
        let k = (-e2) as u32;
        pow5_mul(&mut big, k);
        let digits = to_decimal_digits(&big);
        let point_pos = digits.len() as i32 - k as i32;
        format_g(digits, point_pos, neg)
    }
}

/// Shift bignum left by `bits`.
fn shl_bits(a: &mut Vec<u32>, bits: u32) {
    let words = (bits / 32) as usize;
    let rem = bits % 32;
    if rem > 0 {
        let mut carry = 0u32;
        for limb in a.iter_mut() {
            let new_carry = *limb >> (32 - rem);
            *limb = (*limb << rem) | carry;
            carry = new_carry;
        }
        if carry > 0 {
            a.push(carry);
        }
    }
    if words > 0 {
        let mut shifted = vec![0u32; words];
        shifted.extend_from_slice(a);
        *a = shifted;
    }
}

/// Multiply bignum by 5^k.
fn pow5_mul(a: &mut Vec<u32>, k: u32) {
    const POW5_13: u32 = 1220703125; // 5^13, largest power of 5 fitting u32
    let chunks = k / 13;
    let rem = k % 13;
    for _ in 0..chunks {
        mul_small(a, POW5_13);
    }
    let mut r = 1u32;
    for _ in 0..rem {
        r *= 5;
    }
    if r > 1 {
        mul_small(a, r);
    }
}

/// Multiply bignum by a small factor.
fn mul_small(a: &mut Vec<u32>, x: u32) {
    let mut carry = 0u64;
    for limb in a.iter_mut() {
        let t = (*limb as u64) * (x as u64) + carry;
        *limb = t as u32;
        carry = t >> 32;
    }
    while carry > 0 {
        a.push(carry as u32);
        carry >>= 32;
    }
}

/// Convert bignum to exact decimal digits (values 0..=9, most significant
/// first, no leading zeros).
fn to_decimal_digits(a: &[u32]) -> Vec<u8> {
    let mut limbs = a.to_vec();
    let mut groups: Vec<u32> = Vec::new(); // little-endian base 1e9
    while !limbs.is_empty() {
        let mut rem = 0u64;
        for i in (0..limbs.len()).rev() {
            let cur = (rem << 32) | limbs[i] as u64;
            limbs[i] = (cur / 1_000_000_000) as u32;
            rem = cur % 1_000_000_000;
        }
        while let Some(&0) = limbs.last() {
            limbs.pop();
        }
        groups.push(rem as u32);
    }
    let mut digits: Vec<u8> = Vec::new();
    for idx in (0..groups.len()).rev() {
        let g = groups[idx];
        if idx == groups.len() - 1 {
            // most significant group: no zero padding
            let s = g.to_string();
            digits.extend(s.bytes().map(|b| b - b'0'));
        } else {
            let mut div = 100_000_000u32;
            while div > 0 {
                digits.push(((g / div) % 10) as u8);
                div /= 10;
            }
        }
    }
    digits
}

/// Apply the `%g` layout with precision 6 to exact decimal digits.
/// `d` holds the exact significant digits of the value, `point_pos` the count
/// of digits left of the decimal point in the unrounded expansion.
fn format_g(mut d: Vec<u8>, mut point_pos: i32, neg: bool) -> String {
    const P: usize = 6; // default precision of std::cout / %g

    // Round to P significant digits, round-half-even on exact ties.
    if d.len() > P {
        let first_dropped = d[P];
        let rest_nonzero = d[P + 1..].iter().any(|&x| x != 0);
        let round_up =
            first_dropped > 5 || (first_dropped == 5 && (rest_nonzero || d[P - 1] % 2 == 1));
        d.truncate(P);
        if round_up {
            let mut i = P;
            loop {
                if i == 0 {
                    d.insert(0, 1);
                    point_pos += 1;
                    break;
                }
                i -= 1;
                if d[i] == 9 {
                    d[i] = 0;
                } else {
                    d[i] += 1;
                    break;
                }
            }
        }
    }
    // %g strips trailing zeros.
    while d.len() > 1 && *d.last().unwrap() == 0 {
        d.pop();
    }

    let x = point_pos - 1; // decimal exponent in d.ddd form
    let mut out = String::new();
    if neg {
        out.push('-');
    }

    if x < -4 || x >= P as i32 {
        // Scientific notation: d[.ddd]e±XX (exponent at least two digits).
        out.push((b'0' + d[0]) as char);
        if d.len() > 1 {
            out.push('.');
            for &digit in &d[1..] {
                out.push((b'0' + digit) as char);
            }
        }
        out.push('e');
        out.push(if x < 0 { '-' } else { '+' });
        let ax = x.abs();
        if ax < 10 {
            out.push('0');
        }
        out.push_str(&ax.to_string());
    } else if x >= 0 {
        // Fixed notation with an integer part.
        let ip_len = (x + 1) as usize;
        if d.len() >= ip_len {
            for &digit in &d[..ip_len] {
                out.push((b'0' + digit) as char);
            }
            if d.len() > ip_len {
                out.push('.');
                for &digit in &d[ip_len..] {
                    out.push((b'0' + digit) as char);
                }
            }
        } else {
            for &digit in &d {
                out.push((b'0' + digit) as char);
            }
            for _ in 0..(ip_len - d.len()) {
                out.push('0');
            }
        }
    } else {
        // Fixed notation, 0.000ddd style (x in -4..=-1).
        out.push_str("0.");
        for _ in 0..(-x - 1) {
            out.push('0');
        }
        for &digit in &d {
            out.push((b'0' + digit) as char);
        }
    }
    out
}

