#[path = "src/cppfmt.rs"]
mod cppfmt;

use std::io::{BufRead, BufWriter, Write};

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    if mode == "gen" {
        let n: u64 = std::env::args().nth(2).unwrap().parse().unwrap();
        let stdout = std::io::stdout();
        let mut out = BufWriter::new(stdout.lock());
        let mut emit = |bits: u64| writeln!(out, "{:016x}", bits).unwrap();
        // targeted cases
        let specials: Vec<f64> = vec![
            0.0, -0.0, 1.0, -1.0, 0.5, 2.5, 1.5, 0.15625, 14892.7, 34088.0, 56960.0,
            85865.7, 117820.0, 100000.0, 1000000.0, 999999.5, 999999.4999999999,
            0.0001, 0.00001, 0.000099999999, 1e-5, 1e-4, 1e15, 1e16, 123456.5,
            123456.500001, 9.999995e5, 1.0000005, f64::MAX, f64::MIN_POSITIVE,
            f64::MIN_POSITIVE / 2.0, 5e-324, f64::INFINITY, f64::NEG_INFINITY,
            f64::NAN, -f64::NAN, std::f64::consts::PI, 2.675, 0.125, 1023.5,
            1048575.5, 0.30000000000000004,
        ];
        for v in specials {
            emit(v.to_bits());
        }
        // exact decimal ties: k * 2^-m for small k (exact .5 endings)
        for k in 1u64..2000 {
            for m in 1u32..20 {
                let v = k as f64 / (1u64 << m) as f64;
                emit(v.to_bits());
            }
        }
        // integers around %g rounding boundaries
        for v in 99999u64..1000001 {
            emit(v as f64 as u64 as f64 as u64); // noop guard
            emit((v as f64).to_bits());
            emit((v as f64 + 0.5).to_bits());
            emit((v as f64 - 0.5).to_bits());
        }
        // powers of 10 and neighbours
        let mut p = 1e-320;
        while p < 1e300 {
            emit(p.to_bits());
            emit((p * 1.0000001).to_bits());
            p *= 10.0;
        }
        // random bit patterns (xorshift64*)
        let mut s: u64 = 0x9e3779b97f4a7c15;
        for _ in 0..n {
            s ^= s << 13;
            s ^= s >> 7;
            s ^= s << 17;
            emit(s);
        }
        return;
    }
    // fmt mode: hex bits per line on stdin
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        if line.is_empty() {
            continue;
        }
        let bits = u64::from_str_radix(line.trim(), 16).unwrap();
        let v = f64::from_bits(bits);
        writeln!(out, "{}", cppfmt::format_cpp_double(v)).unwrap();
    }
}

