#[path = "/tmp/check/clipper_stub.rs"]
mod clipper;
#[path = "/output/src/offset.rs"]
mod offset;

use clipper::{Path64, Paths64, Point64};
use offset::{inflate_paths, EndType, JoinType};

fn square() -> Paths64 {
    let p: Path64 = vec![
        Point64::new(200, 200),
        Point64::new(250, 200),
        Point64::new(250, 250),
        Point64::new(200, 250),
    ];
    vec![p]
}

fn show(tag: &str, r: &Paths64) {
    let nv: usize = r.iter().map(|p| p.len()).sum();
    println!("{}: paths={} verts={}", tag, r.len(), nv);
    for p in r {
        let pts: Vec<String> = p.iter().map(|q| format!("({},{})", q.x, q.y)).collect();
        println!("   {}", pts.join(" "));
    }
}

